def lis(arr):
    if not arr:
        return 0
    tails = []
    for val in arr:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < val:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(val)
        else:
            tails[lo] = val
    return len(tails)



